script:
frappe.ui.form.on('Sales Order Item', {
    rate: function(frm, cdt, cdn) {
        calcular_diferencia(frm, cdt, cdn);
    },
    custom_precio_walmart: function(frm, cdt, cdn) {
        calcular_diferencia(frm, cdt, cdn);
    }
});

function calcular_diferencia(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    let precio_json = parseFloat(row.custom_precio_walmart) || 0;
    let precio_erp = parseFloat(row.rate) || 0;

    let diferencia = precio_json - precio_erp;
    row.custom_diferencia_precio = parseFloat(diferencia.toFixed(6));

    frm.refresh_field('items'); // refresca toda la tabla
}
